<script setup>


import {ref, computed} from 'vue'
import QueryEditor from '../shared/components/QueryEditor.vue'
import HelpTip from '../shared/components/HelpTip.vue'
import QueryResults from '../shared/components/QueryResults.vue'
import RedisReadResults from '../shared/components/RedisReadResults.vue'
const props=defineProps({modelValue:String,kind:String,disabled:Boolean,policy:Object,result:Object,previous:Object,executedText:String,fields:Array,recent:Array,canChange:Boolean,cancellable:Boolean})
const emit=defineEmits(['update:modelValue','execute','pin','change','load','inspect-table','inspect-key','clear-key','cancel'])
const editor=ref(null),history=ref(false),outdated=computed(()=>props.result&&(props.modelValue||'').trim()!==(props.executedText||'').trim())
defineExpose({focus:()=>focusControl(editor.value)})
function load(body){history.value=false;emit('load',body)}

import {focusControl} from '../shared/focusControl.js'


import {Badge,Button,Empty,EmptyContent,EmptyDescription,EmptyHeader,Popover,PopoverContent,PopoverTrigger} from '../shared/shadcn-ui.js'
</script>
<template><section :aria-label="kind==='dbms'?'自定义 SQL 查询':'Redis 命令控制台'" class="query-console"><div class="console-toolbar"><b>{{kind==='dbms'?'SQL 查询':'命令控制台'}}</b><Badge variant="secondary">只读</Badge><HelpTip text="执行编辑器中选中的内容；没有选中时执行全文。快捷键：Ctrl / ⌘ + Enter。"/><div class="console-toolbar-actions"><Popover v-model:open="history"><PopoverTrigger as-child><Button variant="outline" size="default" type="button" :disabled="(disabled)">最近查询 {{recent?.length||0}}</Button></PopoverTrigger><PopoverContent class="max-h-[80dvh] max-w-[calc(100vw-2rem)] overflow-auto" align="end" :style="{width:'min(360px,75vw)',maxHeight:'min(360px,65vh)',overflow:'auto'}"><div class="history-menu"><Empty v-if="!recent?.length"><EmptyHeader><EmptyDescription>{{"暂无查询记录"}}</EmptyDescription></EmptyHeader></Empty><Button v-for="(item,i) in recent" :key="i" @click="load(item.body)" variant="outline" size="default" type="button" :disabled="(disabled)"><small>{{item.body.environment}} · {{item.rows}} 行</small><code>{{item.body.sql||item.body.commands}}</code></Button></div></PopoverContent></Popover><Button v-if="disabled&&cancellable" @click="emit('cancel')" variant="outline" size="default" type="button">取消查询</Button><Button @click="editor?.execute()" class="execute-button" variant="default" size="default" type="button" :disabled="(disabled||!policy)">{{disabled?'执行中…':policy?.query_approval?'提交查询申请':'执行只读查询'}}</Button></div></div><div class="console-panes"><div class="console-editor"><QueryEditor ref="editor" :model-value="modelValue" :kind="kind" :disabled="disabled" :suggestions="(fields||[]).slice(0,50)" @update:model-value="emit('update:modelValue',$event)" @execute="emit('execute',$event)"/><div class="console-editor-footer"><Button @click="emit('change')" variant="outline" size="default" type="button" :disabled="(disabled||!canChange)">以此新建变更</Button><small>{{canChange?'查询内容作为核对依据，写操作进入变更流程。':'当前为直接连接；变更需关联应用资源。'}}</small></div></div><div class="console-results"><div v-if="result" class="result-source"><small v-if="outdated">显示上次执行结果；编辑器已修改或仅执行了选中片段。</small><Popover><PopoverTrigger as-child><Button variant="ghost" size="sm" type="button">查看已执行内容</Button></PopoverTrigger><PopoverContent class="max-h-[80dvh] max-w-[calc(100vw-2rem)] overflow-auto" align="end" :style="{maxWidth:'min(560px,80vw)',maxHeight:'50vh',overflow:'auto'}"><pre class="executed-statement">{{executedText}}</pre></PopoverContent></Popover></div><RedisReadResults v-if="kind==='redis'" :result="result" :disabled="disabled" @load="emit('update:modelValue',$event)" @inspect="emit('inspect-key',$event)" @clear="emit('clear-key',$event)"/><QueryResults :result="result" :previous="previous" @pin="emit('pin')" @inspect-table="emit('inspect-table',$event)"/><div v-if="!result" class="console-empty"><b>{{disabled?'正在查询…':'查询结果'}}</b><p>{{disabled?'结果将在此处显示。':'编写 SQL / 命令后点击执行，或选中一段内容按 Ctrl / ⌘ + Enter。'}}</p></div></div></div></section></template>
<style scoped>.result-source{display:flex;gap:8px;align-items:center;flex-shrink:0;font-size:.75rem;margin-bottom:8px;position:relative}.result-source>small{color:var(--warn);flex:1}.result-source pre{position:absolute;right:0;top:100%;z-index:10;max-height:180px;overflow:auto;width:min(360px,100%);padding:10px;white-space:pre-wrap;overflow-wrap:anywhere;border:1px solid var(--border);background:var(--panel);font:.75rem/1.6 var(--mono)}
.query-console{container:query-console / inline-size;display:flex;flex-direction:column;height:100%;min-height:0;min-width:0}.console-toolbar{display:flex;align-items:center;gap:10px;flex-shrink:0;margin-bottom:12px;position:relative;flex-wrap:wrap}.console-toolbar-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-left:auto}.console-panes{display:grid;grid-template-columns:minmax(260px,.9fr) minmax(300px,1.1fr);gap:16px;flex:1;min-height:0;min-width:0}.console-editor,.console-results{min-height:0;min-width:0;display:flex;flex-direction:column}.console-editor{border-right:1px solid var(--border);padding-right:16px}.console-editor :deep(.query-code){display:flex;flex-direction:column;flex:1;min-height:0}.console-editor :deep(.code-surface){flex:1;min-height:120px;overflow:hidden}.console-editor :deep(.code-surface .cm-editor){height:100%}.console-editor :deep(.completion){max-height:64px;overflow:auto;flex-shrink:0}.console-editor-footer{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding-top:12px;flex-shrink:0}.console-editor-footer small{font-size:.75rem;color:var(--muted-foreground)}.console-results{overflow:hidden}.console-results :deep(.query-results){display:flex;flex-direction:column;min-height:0;flex:1;margin:0;padding:0;border:0}.console-results :deep(.result-scroll){flex:1;min-height:0;max-height:none;resize:none}.console-results :deep(.result-head){padding-bottom:8px}.console-results :deep(.redis-read-results){max-height:180px;overflow:auto;flex-shrink:0;margin:0 0 12px}.console-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;flex:1;text-align:center;color:var(--muted-foreground);padding:24px;font-size:.875rem}.console-empty p{line-height:1.8}.console-history{position:relative;font-size:.75rem;margin-left:auto}.history-menu{display:grid;gap:6px}.history-menu code{white-space:pre-wrap;overflow-wrap:anywhere;max-height:80px;overflow:hidden;font-size:.75rem}.history-menu small{color:var(--muted-foreground)}@container query-console (max-width:56rem){.console-panes{grid-template-columns:minmax(0,1fr);grid-template-rows:minmax(160px,.45fr) minmax(180px,.55fr);gap:12px}.console-editor{border-right:0;border-bottom:1px solid var(--border);padding-right:0;padding-bottom:12px}.console-editor-footer{padding-top:6px}}@media(max-width:760px){.console-editor-footer small{display:none}.console-panes{grid-template-rows:minmax(140px,.4fr) minmax(160px,.6fr)}}</style>

<style scoped>.executed-statement{white-space:pre-wrap;overflow-wrap:anywhere;font:.75rem/1.6 var(--mono);margin:0}</style>
